import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"事件 API","description":"","frontmatter":{},"headers":[],"relativePath":"modules/skills/events.md","filePath":"modules/skills/events.md","lastUpdated":0}`),a={name:`modules/skills/events.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="事件-api" tabindex="-1">事件 API <a class="header-anchor" href="#事件-api" aria-label="Permalink to “事件 API”">​</a></h1><p>Skills 事件位于 <code>emaki.jiuwu.craft.skills.api.event</code>，同步发布在技能玩家 owner thread。异步施法会先回到 owner thread，再发布 pre/post 事件。</p><table tabindex="0"><thead><tr><th>事件</th><th>触发时机</th><th>Cancellable</th><th>可修改字段</th><th>取消/结果效果</th><th>runtime 路径</th></tr></thead><tbody><tr><td><code>SkillPreCastEvent</code></td><td>条件、冷却、资源检查通过后，执行技能 effect 前</td><td>是</td><td>无</td><td>停止 effect、资源与冷却提交</td><td><code>CastAttemptService</code> 的 active/passive、<code>cast</code> 与 <code>castByTrigger</code> 路径</td></tr><tr><td><code>SkillPostCastEvent</code></td><td>effect 成功，资源与冷却已通过当前 session 提交后</td><td>否</td><td>无</td><td>post 通知，不可回滚</td><td>成功的 <code>CastAttemptService.finalizeAttempt</code>；失败或 source lost 不发</td></tr><tr><td><code>SkillPreUpgradeEvent</code></td><td>升级校验通过后、扣费和摇点前</td><td>是</td><td><code>successRate</code></td><td>停止扣费与升级</td><td><code>SkillUpgradeService</code></td></tr><tr><td><code>SkillUpgradeEvent</code></td><td>升级尝试成功或失败结果已应用后</td><td>否</td><td>无</td><td>post 通知</td><td><code>SkillUpgradeService</code></td></tr><tr><td><code>PlayerSkillSlotChangeEvent</code></td><td>equip、unequip、bind-trigger 写入前</td><td>是</td><td>无</td><td>阻止槽位变更</td><td><code>PlayerSkillStateService</code> 三条状态路径</td></tr></tbody></table><h2 id="事件字段" tabindex="-1">事件字段 <a class="header-anchor" href="#事件字段" aria-label="Permalink to “事件字段”">​</a></h2><table tabindex="0"><thead><tr><th>事件</th><th>只读字段</th><th>可写字段</th></tr></thead><tbody><tr><td><code>SkillPreCastEvent</code></td><td><code>player</code>、<code>skillId</code>、<code>triggerId</code></td><td><code>cancelled</code></td></tr><tr><td><code>SkillPostCastEvent</code></td><td><code>player</code>、<code>skillId</code>、<code>triggerId</code></td><td>无（不含 HandlerList 之外的字段）</td></tr><tr><td><code>SkillPreUpgradeEvent</code></td><td><code>player</code>、<code>skillId</code>、<code>currentLevel</code>、<code>targetLevel</code>、<code>maxLevel</code></td><td><code>cancelled</code>、<code>successRate</code></td></tr><tr><td><code>SkillUpgradeEvent</code></td><td><code>player</code>、<code>skillId</code>、<code>fromLevel</code>、<code>toLevel</code>、<code>successRate</code>、<code>success</code>、<code>downgraded</code></td><td>无</td></tr><tr><td><code>PlayerSkillSlotChangeEvent</code></td><td><code>player</code>、<code>slotIndex</code>、<code>skillId</code>、<code>triggerId</code>、<code>action</code></td><td><code>cancelled</code></td></tr></tbody></table><p><code>PlayerSkillSlotChangeEvent.Action</code> 取值：<code>EQUIP</code>（装配技能）、<code>UNEQUIP</code>（清空槽位）、<code>BIND_TRIGGER</code>（绑定触发器）。<code>UNEQUIP</code> 时 <code>skillId</code> 是原先绑定的技能 id，<code>triggerId</code> 只在 <code>BIND_TRIGGER</code> 时非空。</p><h2 id="边界说明" tabindex="-1">边界说明 <a class="header-anchor" href="#边界说明" aria-label="Permalink to “边界说明”">​</a></h2><ul><li><code>SkillPostCastEvent</code> 只包含 player、skillId、triggerId，且绝不 Cancellable。</li><li><code>SkillPreUpgradeEvent</code> 在扣费之前发布，因此取消它不会产生已扣费用。</li><li><code>SkillUpgradeEvent</code> 在等级（或失败惩罚）已经应用之后发布，监听器只能观察，不能改变结果。</li><li>Script action 与外部技能来源 provider 是扩展执行点，不会凭注册本身触发事件；只有实际进入中央 cast/upgrade/slot service 的操作才覆盖这些事件。</li><li>事件由插件同步调用，监听器不得在其中执行阻塞操作或访问其他实体的 Bukkit 状态。</li></ul>`,8)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};